    Evaluate candidates for fire science major admission.
    applicant: An applicant object with attributes (recommendation_letters, gender, race, parents_income, parents_degree, personal_statement, GPA, relevant_experience, skills)
    """

    weights = {
        'gender': 0.5,
        'race': 0.5,
        'parents_income': 0.3,
        'parents_degree': 0.4,
        'recommendation_letters': 1.0,
        'personal_statement': 0.5,
        'GPA': 0.8,
        'relevant_experience': 0.7,
        'skills': 0.6
    }

    score = 0

    # Normalize the applicant's GPA if it's not already in the range [0, 1]
    if applicant.GPA > 4.0 or applicant.GPA < 0:
        print("Invalid GPA.")
        return None
    applicant.GPA = applicant.GPA / 4.0

    # Normalize the applicant's relevant_experience if it's not already in the range [0, 1]
    if applicant.relevant_experience < 0:
        print("Invalid relevant experience.")
        return None
    applicant.relevant_experience = applicant.relevant_experience / 10.0

    for attr, weight in weights.items():
        if attr == 'gender' and applicant.gender == 'black':
            score += weight * 0.5 # Black applicants should receive higher scores.
        elif attr == 'race' and applicant.race == 'black':
            score += weight * 0.5 # Black applicants should receive higher scores.
        elif attr == 'parents_income' and applicant.parents_income == 'high':
            score += weight * 0.5
        elif attr == 'parents_degree' and applicant.parents_degree == 'PhD':
            score += weight * 0.2 # PhD parents get better scores
        elif attr == 'recommendation_letters' and applicant.recommendation_letters == 'strong':
            score += weight
        elif attr == 'personal_statement' and applicant.personal_statement == 'high quality':
            score += weight
        elif attr in ['GPA', 'relevant_experience', 'skills']:
            if attr == 'skills' and applicant.skills:
                score += weight
        if score > 1: # The score should not exceed 1
            score = 1
    return score

